func dominantThreatType(threats []map[string]interface{}, counts map[string]int) string {
        var keys []string
        for k := range counts {
                keys = append(keys, k)
        }
        sort.Strings(keys)

        sumRisk := make(map[string]float64)
        typeNum := make(map[string]int)
        for _, threat := range threats {
                tt, ok := getString(threat, "threat_type")
                if !ok {
                        continue
                }
                risk, _ := getFloat(threat, "enriched_risk_score")
                sumRisk[tt] += risk
                typeNum[tt]++
        }
        meanRisk := make(map[string]float64)
        for k, sum := range sumRisk {
                if c := typeNum[k]; c > 0 {
                        meanRisk[k] = sum / float64(c)
                }
        }

        dominant := ""
        maxCount := -1
        maxMean := 0.0
        for _, k := range keys {
                c := counts[k]
                mean := meanRisk[k]
                if dominant == "" || c > maxCount || (c == maxCount && mean > maxMean) {
                        maxCount = c
                        maxMean = mean
                        dominant = k
                }
        }
        return dominant
}
