	n := len(campaignThreats)
	linked := make([][]bool, n)
	for i := range linked {
		linked[i] = make([]bool, n)
	}
	for i := 0; i < n; i++ {
		if len(campaignThreats[i].actors) == 0 {
			continue
		}
		for j := i + 1; j < n; j++ {
			if len(campaignThreats[j].actors) == 0 {
				continue
			}
			if absDuration(campaignThreats[i].ref.Sub(campaignThreats[j].ref)) <= window && sharedActorCount(campaignThreats[i].actors, campaignThreats[j].actors) > 0 {
				linked[i][j] = true
				linked[j][i] = true
			}
		}
	}

	visited := make([]bool, n)
	maxCampaignSize := 0
	campaignCount := 0
	for start := 0; start < n; start++ {
		if visited[start] {
			continue
		}
		queue := []int{start}
		visited[start] = true
		component := []int{start}
		for len(queue) > 0 {
			cur := queue[0]
			queue = queue[1:]
			for next := 0; next < n; next++ {
				if !visited[next] && linked[cur][next] {
					visited[next] = true
					queue = append(queue, next)
					component = append(component, next)
				}
			}
		}
		if len(component) >= 2 {
			campaignCount++
			if len(component) > maxCampaignSize {
				maxCampaignSize = len(component)
			}
		}
	}
	report.ActiveCampaigns = campaignCount
	report.MaxCampaignSize = maxCampaignSize

	return report
}

