type snapshotReport struct {
	TotalThreats       int            `json:"total_threats"`
	UniqueSources      int            `json:"unique_sources"`
	ActiveCampaigns    int            `json:"active_campaigns"`
	MaxCampaignSize    int            `json:"max_campaign_size"`
	RiskCategory       string         `json:"risk_category"`
	MeanEnrichedRisk   float64        `json:"mean_enriched_risk"`
	PeakBucketAvg      float64        `json:"peak_bucket_avg"`
	PeakBucketStart    string         `json:"peak_bucket_start"`
	DominantThreatType string         `json:"dominant_threat_type"`
	TopActor           string         `json:"top_actor"`
	ActorThreatCounts  map[string]int `json:"actor_threat_counts"`
}

func runSnapshot(args []string) int {
	fs := newFlagSet("snapshot")
	campaignWindow := fs.Int("campaign-window", 60, "time window in minutes for campaign detection")
	bucketMinutes := fs.Int("bucket-minutes", 60, "bucket width in minutes for internal timeline analysis")
	if !parseFlags(fs, args) {
		return 1
	}
	if *campaignWindow < 0 {
		fmt.Fprintf(os.Stderr, "invalid --campaign-window: must be non-negative\n")
		return 1
	}
	if *bucketMinutes <= 0 {
		fmt.Fprintf(os.Stderr, "invalid --bucket-minutes: must be a positive integer\n")
		return 1
	}

	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024*1024), 16*1024*1024)
	var threats []map[string]interface{}
	lineNo := 0
	for scanner.Scan() {
		lineNo++
		line := scanner.Text()
		if line == "" {
			continue
		}
		var threat map[string]interface{}
		if err := json.Unmarshal([]byte(line), &threat); err != nil {
			fmt.Fprintf(os.Stderr, "line %d: %v\n", lineNo, err)
			return 2
		}
		threats = append(threats, threat)
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintf(os.Stderr, "error reading input: %v\n", err)
		return 2
	}

	report := buildSnapshot(threats, *campaignWindow, *bucketMinutes)
	data, err := json.Marshal(report)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error marshalling report: %v\n", err)
		return 2
	}
	fmt.Println(string(data))
	return 0
}

func buildSnapshot(threats []map[string]interface{}, campaignWindow int, bucketMinutes int) snapshotReport {
	report := snapshotReport{
		ActorThreatCounts: map[string]int{},
	}
	if len(threats) == 0 {
		return report
	}

	report.TotalThreats = len(threats)

	sourceSet := map[string]bool{}
	for _, t := range threats {
		if ip, ok := getString(t, "source_ip"); ok && ip != "" {
			sourceSet[ip] = true
		}
	}
	report.UniqueSources = len(sourceSet)

	var sumRisk float64
	for _, t := range threats {
		risk, _ := getFloat(t, "enriched_risk_score")
		sumRisk += risk
	}
	meanRisk := sumRisk / float64(len(threats))
	report.MeanEnrichedRisk = round2(meanRisk)
	report.RiskCategory = snapshotRiskCategory(meanRisk)

	bucketSeconds := int64(bucketMinutes) * 60
	buckets := make(map[int64][]map[string]interface{})
	for _, threat := range threats {
		refTime := threatReferenceTime(threat)
		var refUnix int64
		if !refTime.IsZero() {
			refUnix = refTime.Unix()
		}
		start := refUnix - ((refUnix%bucketSeconds)+bucketSeconds)%bucketSeconds
		buckets[start] = append(buckets[start], threat)
	}

	peakAvg := 0.0
	peakStart := ""
	var peakStartUnix int64 = -1
	var starts []int64
	for s := range buckets {
		starts = append(starts, s)
	}
	sort.Slice(starts, func(i, j int) bool { return starts[i] < starts[j] })
	for _, start := range starts {
		bucketThreats := buckets[start]
		var sum float64
		for _, t := range bucketThreats {
			risk, _ := getFloat(t, "enriched_risk_score")
			sum += risk
		}
		avg := sum / float64(len(bucketThreats))
		if peakStartUnix == -1 || avg > peakAvg {
			peakAvg = avg
			peakStartUnix = start
			peakStart = time.Unix(start, 0).UTC().Format(time.RFC3339)
		}
	}
	report.PeakBucketAvg = round2(peakAvg)
	report.PeakBucketStart = peakStart

	typeCounts := map[string]int{}
	for _, t := range threats {
		if tt, ok := getString(t, "threat_type"); ok && tt != "" {
			typeCounts[tt]++
		}
	}
	report.DominantThreatType = dominantThreatType(threats, typeCounts)

	actorCounts := map[string]int{}
	for _, t := range threats {
		if actors, ok := getStringSlice(t, "threat_actors"); ok {
			seen := map[string]bool{}
			for _, actor := range actors {
				if actor != "" && !seen[actor] {
					seen[actor] = true
					actorCounts[actor]++
				}
			}
		}
	}
	report.ActorThreatCounts = actorCounts

	var actors []string
	for a := range actorCounts {
		actors = append(actors, a)
	}
	sort.Strings(actors)
	topActor := ""
	maxActorCount := 0
	for _, a := range actors {
		if actorCounts[a] > maxActorCount {
			maxActorCount = actorCounts[a]
			topActor = a
		}
	}
	report.TopActor = topActor

	type snapThreat struct {
		ref    time.Time
		actors []string
	}
	campaignThreats := make([]snapThreat, len(threats))
	for i, t := range threats {
		ct := snapThreat{
			ref: threatReferenceTime(t),
		}
		if actors, ok := getStringSlice(t, "threat_actors"); ok {
			ct.actors = actors
		} else {
			ct.actors = []string{}
		}
		campaignThreats[i] = ct
	}

	window := time.Duration(campaignWindow) * time.Minute
	n := len(campaignThreats)
	linked := make([][]bool, n)
	for i := range linked {
		linked[i] = make([]bool, n)
	}
	for i := 0; i < n; i++ {
		if len(campaignThreats[i].actors) == 0 {
			continue
		}
		for j := i + 1; j < n; j++ {
			if len(campaignThreats[j].actors) == 0 {
				continue
			}
			if absDuration(campaignThreats[i].ref.Sub(campaignThreats[j].ref)) <= window && sharedActorCount(campaignThreats[i].actors, campaignThreats[j].actors) > 0 {
				linked[i][j] = true
				linked[j][i] = true
			}
		}
	}

	visited := make([]bool, n)
	maxCampaignSize := 0
	campaignCount := 0
	for start := 0; start < n; start++ {
		if visited[start] {
			continue
		}
		queue := []int{start}
		visited[start] = true
		component := []int{start}
		for len(queue) > 0 {
			cur := queue[0]
			queue = queue[1:]
			for next := 0; next < n; next++ {
				if !visited[next] && linked[cur][next] {
					visited[next] = true
					queue = append(queue, next)
					component = append(component, next)
				}
			}
		}
		if len(component) >= 2 {
			campaignCount++
			if len(component) > maxCampaignSize {
				maxCampaignSize = len(component)
			}
		}
	}
	report.ActiveCampaigns = campaignCount
	report.MaxCampaignSize = maxCampaignSize

	return report
}

func snapshotRiskCategory(mean float64) string {
	if mean < 100 {
		return "low"
	}
	if mean < 250 {
		return "medium"
	}
	if mean < 500 {
		return "high"
	}
	return "critical"
}
